def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    # Full-span divider
    div = None
    for r, row in enumerate(grid):
        if row[0] != bg and all(x == row[0] for x in row):
            div = ('h', r, row[0])
            break
    if div is None:
        for c in range(w):
            color = grid[0][c]
            if color != bg and all(grid[r][c] == color for r in range(h)):
                div = ('v', c, color)
                break
    if div is None:
        return out
    axis, pos, sep = div
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, sep)]
    if not cells:
        return out
    if axis == 'h':
        lo, hi = min(r for r,c,v in cells), max(r for r,c,v in cells)
        if hi < pos:
            delta, stripe = pos - 1 - hi, None
            stripe = lo + delta - 1
        elif lo > pos:
            delta = pos + 1 - lo
            stripe = hi + delta + 1
        else:
            return out
        for r,c,v in cells:
            out[r][c] = bg
        for r,c,v in cells:
            out[r+delta][c] = v
        if 0 <= stripe < h:
            out[stripe] = [8] * w
    else:
        lo, hi = min(c for r,c,v in cells), max(c for r,c,v in cells)
        if hi < pos:
            delta = pos - 1 - hi
            stripe = lo + delta - 1
        elif lo > pos:
            delta = pos + 1 - lo
            stripe = hi + delta + 1
        else:
            return out
        for r,c,v in cells:
            out[r][c] = bg
        for r,c,v in cells:
            out[r][c+delta] = v
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8
    return out

